package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.jlinalg.study.StudyProject;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyReferenceTextTest {
    @TempDir Path root;
    private static final String DOI="10.5555/native-reference-text";
    private static final String META="{\"resultList\":{\"result\":[{\"source\":\"MED\",\"id\":\"123\",\"pmcid\":\"PMC123\",\"doi\":\""+DOI+"\",\"title\":\"Synthetic primary source\"}]}}";
    private static String xml(String doi){return "<article><front><article-meta><article-id pub-id-type=\"doi\">"+doi+"</article-id><article-id pub-id-type=\"pmid\">123</article-id><title-group><article-title>Synthetic primary source</article-title></title-group><permissions><license>CC BY synthetic fixture</license></permissions><abstract><p>Bounded synthetic abstract.</p></abstract></article-meta></front><body><sec><title>Results</title><p>Controlled model <italic>intervention</italic> changed the readout.</p><p>UNAPPROVED_FULL_BODY_SENTINEL</p></sec></body></article>";}
    private Path fetch(String name,boolean text,boolean offline,StudyPublicEvidence client)throws Exception{
        Path project=root.resolve("policy-"+name);Files.createDirectory(project);Files.writeString(project.resolve("resolved-study.yaml"),"resources: {downloads: automatic}\n");Path request=root.resolve(name+".yaml");StudyPublicEvidence.write(request,Map.of("schema_version",1,"references",List.of(Map.of("id",DOI,"rationale","Synthetic source grounding only","full_text",text))));return StudyCitationSources.fetch(project,request,root.resolve(name),StudyProject.Actor.human("test"),offline,client);
    }
    @Test void explicitFullTextRetainsIdentityScopeLicenseRawAuditAndHashPinnedMembership()throws Exception {
        var calls=new ArrayList<String>();Path bundle=fetch("complete",true,false,new StudyPublicEvidence(uri->{calls.add(uri.toString());return new StudyPublicEvidence.Reply(200,uri.getPath().endsWith("fullTextXML")?xml(DOI):META);}));assertEquals(2,calls.size());assertTrue(calls.get(1).endsWith("PMC123/fullTextXML"));StudyCitationSources.verify(bundle.resolve("metadata/manifest.yaml"));var source=StudyPublicEvidence.map(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/full-text-sources.yaml")).get("sources")).get(0));assertEquals("available",source.get("status"));assertTrue(source.get("license").toString().contains("CC BY"));Path text=bundle.resolve(source.get("text_file").toString());assertEquals(source.get("sha256"),FollowupSupport.hash(text));assertTrue(Files.readString(text).contains("Controlled model intervention changed the readout."));assertTrue(Files.readString(bundle.resolve("logs/requests.yaml")).contains("response_format: text"));
        var catalog=StudyYaml.loadArtifact(bundle.resolve("artifacts/reference-catalog.yaml"));var entry=new LinkedHashMap<>(StudyPublicEvidence.map(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/finding-review-source-template.yaml")).get("source_texts")).get(0)));Path manifest=bundle.resolve("metadata/manifest.yaml");entry.put("reference_bundle",Map.of("manifest",manifest.toString(),"sha256",FollowupSupport.hash(manifest)));Path request=root.resolve("review.yaml");Files.writeString(request,"fixture");var revision=Map.<String,Object>of("sections",List.of(),"finding_review",Map.of("source_texts",List.of(entry)));var review=StudyFindingDiscussion.assess(root,request,null,false,revision,Map.of(),catalog);assertTrue(review.report().get("source_texts").toString().contains("verified_native_reference_bundle_member"));assertFalse(StudyAssistance.json(StudyReferenceCatalog.publicMetadata(StudyReferenceCatalog.lookup(catalog,DOI))).contains("UNAPPROVED_FULL_BODY_SENTINEL"));
        entry.put("scope","abstract");var conflict=Map.<String,Object>of("sections",List.of(),"finding_review",Map.of("source_texts",List.of(entry)));assertThrows(java.io.IOException.class,()->StudyFindingDiscussion.assess(root,request,null,false,conflict,Map.of(),catalog));
    }
    @Test void metadataOnlyDefaultDoesNotFetchFullText()throws Exception{var calls=new AtomicInteger();Path bundle=fetch("metadata-only",false,false,new StudyPublicEvidence(uri->{calls.incrementAndGet();assertTrue(uri.getPath().endsWith("search"));return new StudyPublicEvidence.Reply(200,META);}));assertEquals(1,calls.get());assertTrue(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/full-text-sources.yaml")).get("sources")).isEmpty());}
    @Test void unavailableFullTextDoesNotEraseUsableBibliographicMetadata()throws Exception{Path bundle=fetch("missing",true,false,new StudyPublicEvidence(uri->new StudyPublicEvidence.Reply(uri.getPath().endsWith("fullTextXML")?404:200,uri.getPath().endsWith("fullTextXML")?"not available":META)));assertEquals("complete",StudyYaml.loadArtifact(bundle.resolve("metadata/manifest.yaml")).get("state"));assertEquals(1,StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/reference-catalog.yaml")).get("references")).size());assertEquals("unavailable",StudyPublicEvidence.map(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/full-text-sources.yaml")).get("sources")).get(0)).get("status"));assertTrue(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/finding-review-source-template.yaml")).get("source_texts")).isEmpty());}
    @Test void identityConflictAndExternalEntitiesNeverBecomeReviewedFullText()throws Exception{for(String name:List.of("wrong-identity","entity")){String body=name.equals("entity")?"<!DOCTYPE article [<!ENTITY secret SYSTEM 'file:///must-not-read'>]>"+xml(DOI).replace("changed the readout.","&secret;"):xml("10.5555/different");Path bundle=fetch(name,true,false,new StudyPublicEvidence(uri->new StudyPublicEvidence.Reply(200,uri.getPath().endsWith("fullTextXML")?body:META)));var row=StudyPublicEvidence.map(StudyPublicEvidence.list(StudyYaml.loadArtifact(bundle.resolve("artifacts/full-text-sources.yaml")).get("sources")).get(0));assertEquals("unavailable_invalid_or_unsupported_xml",row.get("status"));assertFalse(row.containsKey("text_file"));}}
    @Test void offlinePolicyPreventsBothMetadataAndTextTransport()throws Exception{Path bundle=fetch("offline",true,true,new StudyPublicEvidence(uri->{throw new AssertionError("Offline source transport attempted");}));assertEquals("needs_input",StudyYaml.loadArtifact(bundle.resolve("metadata/manifest.yaml")).get("state"));assertFalse(Files.exists(bundle.resolve("artifacts/full-text")));}
    @Test void fullTextWithoutAnExplicitBooleanOptionIsRejectedBeforeOutput()throws Exception{Path project=Files.createDirectory(root.resolve("policy"));Files.writeString(project.resolve("resolved-study.yaml"),"resources: {downloads: automatic}\n");Path request=root.resolve("bad.yaml");StudyPublicEvidence.write(request,Map.of("schema_version",1,"references",List.of(Map.of("id",DOI,"rationale","fixture","full_text","yes"))));Path output=root.resolve("bad");assertThrows(java.io.IOException.class,()->StudyCitationSources.fetch(project,request,output,StudyProject.Actor.human("test"),false,new StudyPublicEvidence()));assertFalse(Files.exists(output));}
}
